    d.cardSales=[{id:'CS01',card:'CARD02',customer:'林女士 / HY1001',store:'XM',sold:day(-10),expires:day(355),amount:2980,remaining:[{spec:'SP03',times:3},{spec:'SP04',times:2}],initialTimes:5,recognized:0,status:'有效'}];
