  function lineTable(lines,kind){if(kind==='card')return table(['可核销服务规格','次数','操作'],lines.map((l,i)=>[select([['','请选择服务规格'],...optionList({key:'spec',options:'specs'})],l.spec,`name="line-${i}-spec" aria-label="卡内第${i+1}项服务" data-filterable="true"`),`<input type="number" name="line-${i}-times" aria-label="卡内第${i+1}项次数" value="${esc(l.times)}" min="1" step="1">`,link('移除','removeLine',i)]));return lines.map((l,i)=>{const k=S.get(l.type==='sku'?'skus':'equipment',l.item),defs=[S.f('type','类型','select',['sku','equipment'],true),S.ref('item','物料 / 仪器',l.type==='equipment'?'equipment':'skus'),S.f('unit','消耗单位','select',l.type==='equipment'?[k?.unit||'发']:S.unitsFor(l.item),true),S.req('quantity','标准用量','number'),S.req('min','最低用量','number'),S.req('max','最高用量','number'),...(l.type==='sku'?[S.f('alternatives','可选替代料','multi','skus')]:[])];let html=form(defs.map(f=>({...f,key:'line-'+i+'-'+f.key})),Object.fromEntries(Object.entries(l).map(([key,v])=>['line-'+i+'-'+key,v])),'sc-bom');html=html.replace('name="line-'+i+'-type"','onchange="'+esc(call('lineChange',i,'type'))+'" name="line-'+i+'-type"').replace('name="line-'+i+'-item"','onchange="'+esc(call('lineChange',i,'item'))+'" name="line-'+i+'-item"');return contentModule('配方第 '+(i+1)+' 项',html,link('移除','removeLine',i))}).join('')}
  function readLines(el,m){const lines=m.lines||m.contents;lines.forEach((l,i)=>{for(const k of Object.keys(l)){const c=el.querySelector(`[name="line-${i}-${k}"]`);if(c)l[k]=c.multiple?[...c.selectedOptions].map(o=>o.value):c.type==='number'?(c.value===''?'':Number(c.value)):c.value}if(l.type==='equipment')l.alternatives=[]})}
